struct Model {
bool predict(srb_v11_short48_teacher::NewModelRaw raw,const srb_v11_short48_teacher::AFeatures& f,uint32_t& out)const{
out=0xffffffffu;
if(raw.value>0x7fffffffu||f.source>=496||f.target>=496||f.nx>=120||f.tx>=120||f.ny>=550||f.ty>=550)return false;
const int dx=f.dx,dy=f.dy;if(dx<-72||dx>72||dy<-72||dy>72)return false;
const unsigned ax=dx<0?-dx:dx,ay=dy<0?-dy:dy;if(ax+ay>72||(ax<=26&&ay<=26))return false;
const int s=kSourceRow[f.source],t=kTargetRow[f.target];const unsigned p=kTargetPrototype[f.target];
if(s<0||t<0||p>=32)return false;
const unsigned phase=((dx%10+10)%10)*12+(dy%12+12)%12;
const unsigned direction=(dx>0)+2*(dx<0)+3*(dy>0)+6*(dy<0);
const unsigned shape=direction*8+std::min(7u,8*ax/(ax+ay+1));
if(f.native_code!=((phase<<8)|shape))return false;
int c=int(source_phase[s*120+phase])+target_phase[t*120+phase]+source_shape[s*72+shape]+target_shape[t*72+shape];
c+=int(source_x[s*4+f.nx/30])+target_x[t*4+f.tx/30]+source_y[s*11+f.ny/50]+target_y[t*11+f.ty/50];
const unsigned bx=std::min(8u,ax/10),by=std::min(7u,ay/12);
c+=int(source_dx[s*9+bx])+target_dx[t*9+bx]+source_dy[s*8+by]+target_dy[t*8+by]+source_prototype_direction[(s*32+p)*2+(dy<0)];
const int correction=c>=-4?(c+4)/8:-((-c+3)/8);
const int64_t value=std::max<int64_t>(0,int64_t(raw.value)+correction);
if(value>0x7fffffff)return false;out=uint32_t(value);return true;
}
};
